// Expectations execute the original normalizer on data extracted from its TypeScript tests.
use serde_json::{Value, json};
use t3_client::thread_views::composer::web_drafts::normalize_state;
fn projection(state: &Value) -> Value {
    let mut state = state.clone();
    let fields = [
        "draftsByThreadKey",
        "draftThreadsByThreadKey",
        "logicalProjectDraftThreadKeyByLogicalProjectKey",
        "stickyModelSelectionByProvider",
        "stickyOptionsByModelByProvider",
        "stickyActiveProvider",
    ];
    state
        .as_object_mut()
        .expect("state")
        .retain(|key, _| fields.contains(&key.as_str()));
    for (field, known) in [
        (
            "draftsByThreadKey",
            &[
                "prompt",
                "attachments",
                "files",
                "terminalContexts",
                "previewAnnotations",
                "reviewComments",
                "threadContexts",
                "environmentContexts",
                "replyTo",
                "modelSelectionByProvider",
                "activeProvider",
                "modelSelectionExplicit",
                "runtimeMode",
                "interactionMode",
            ][..],
        ),
        (
            "draftThreadsByThreadKey",
            &[
                "threadId",
                "environmentId",
                "projectId",
                "logicalProjectKey",
                "createdAt",
                "runtimeMode",
                "interactionMode",
                "branch",
                "worktreePath",
                "envMode",
                "startFromOrigin",
                "environmentSelection",
                "loadBalancedEnvironmentId",
                "checkoutPullRequest",
                "promotedTo",
            ][..],
        ),
    ] {
        if let Some(map) = state[field].as_object_mut() {
            for draft in map.values_mut() {
                if let Some(fields) = draft.as_object_mut() {
                    fields.retain(|key, _| known.contains(&key.as_str()));
                }
            }
        }
    }
    state
}
#[test]
fn original_historical_normalization_matches_while_unknown_carrier_fields_survive() {
    let cases: Value = serde_json::from_str(GOLDENS).expect("goldens");
    let mut failures = Vec::new();
    for (index, case) in cases.as_array().expect("cases").iter().enumerate() {
        let actual = normalize_state(
            &case["input"],
            "2000-01-01T00:00:00.000Z",
            case["strip"].as_bool().expect("strip"),
        );
        let actual = projection(&actual);
        let expected = projection(&case["expected"]);
        if actual != expected {
            failures.push(format!(
                "case {index}, strip {} input {}\nactual {actual}\nexpected {expected}",
                case["strip"], case["input"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 12:\n{}",
        failures.len(),
        failures
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert_eq!(
        normalize_state(&json!({"future":{"keep":true}}), "now", false)["future"],
        json!({"keep":true})
    );
}
